{
  "id": 10,
  "knowledge": "Resource Utilization Ratio (RUR)",
  "description": "Measures how effectively hub capacity is being used relative to available resources",
  "definition": "RUR = \\frac{hubutilpct}{100} \\times \\frac{storecapm3}{storeavailm3 + 1}"
}

{
  "id": 12,
  "knowledge": "Communication Security Risk (CSR)",
  "description": "Measures the security risk associated with communication systems during disaster response",
  "definition": "CSR = secincidentcount \\times 5 + (100 - reportcompliance) + 90 - (dataqualityvalue \\times 3)"
}

{
  "id": 13,
  "knowledge": "Personnel Effectiveness Ratio (PER)",
  "description": "Evaluates how effectively human resources are utilized in operations",
  "definition": "PER = \\frac{staffingprofile->>'personnel'->>'total'}{(personnelcostsusd / 10000)} \\times \\frac{staffingprofile->>'readiness'->>'availability_percent'}{100}"
}

{
  "id": 14,
  "knowledge": "Market Stability Index (MSI)",
  "description": "Assesses the stability and reliability of disaster response operations over time",
  "definition": "MSI = \\frac{estdurationdays}{365.0} \\times \\frac{deliverysuccessrate}{100.0} \\times \\left(1 - \\frac{secincidentcount}{partnerorgs::integer \\times 10 + 1}\\right) \\times 100, \\text{ where estdurationdays represents operation duration from operations table, deliverysuccessrate captures logistics reliability from transportation table, and secincidentcount/partnerorgs ratio approximates system disruptions per partner organization}"
}

{
  "id": 15,
  "knowledge": "Logistics Performance Metric (LPM)",
  "description": "Measures the overall performance of logistics operations",
  "definition": "LPM = \\frac{totaldeliverytons}{hubcaptons} \\times deliverysuccessrate \\times \\left(1 - \\frac{vehiclebreakrate}{100}\\right) \\times 100"
}

{
  "id": 16,
  "knowledge": "Environmental Impact Factor (EIF)",
  "description": "Quantifies the environmental footprint of disaster response operations",
  "definition": "EIF = carbontons \\times \\left(1 - \\frac{renewenergypct}{100}\\right) + (100 - recyclepct) \\times 0.5"
}

{
  "id": 17,
  "knowledge": "Public Health Resilience Score (PHRS)",
  "description": "Evaluates the resilience of public health systems during disasters",
  "definition": "PHRS = waterqualityindex \\times 0.4 + sanitationcoverage \\times 0.3 + vaccinationcoverage \\times 0.3"
}

{
  "id": 18,
  "knowledge": "Financial Sustainability Ratio (FSR)",
  "description": "Assesses the financial sustainability of disaster response operations",
  "definition": "FSR = \\frac{donorcommitmentsusd}{budgetallotusd} \\times \\left(1 - \\frac{fundsutilpct}{100}\\right) - \\frac{resourcegapsusd}{budgetallotusd}"
}

{
  "id": 19,
  "knowledge": "Beneficiary Satisfaction Index (BSI)",
  "description": "Measures the satisfaction level of aid recipients",
  "definition": "BSI = benefeedbackscore \\times 10 + (commengage\\_numeric \\times 20) + distequityidx \\times 50, \\text{ where commengage\\_numeric maps Low=1, Medium=2, High=3}"
}

{
  "id": 20,
  "knowledge": "Critical Resource Shortage",
  "description": "Identifies situations where essential resources are dangerously depleted",
  "definition": "A condition where storeavailm3 is less than 10% of storecapm3 AND supplyflowstate is 'Strained' or 'Disrupted', indicating severe logistical constraints that may compromise disaster response"
}

{
  "id": 21,
  "knowledge": "High-Risk Response Operation",
  "description": "Identifies disaster operations with elevated risk factors",
  "definition": "Operations where emerglevel is 'Red' or 'Black' AND safetyranking is 'High Risk' AND secincidentcount > 50, indicating dangerous conditions requiring special safety protocols"
}

{
  "id": 22,
  "knowledge": "Resource Optimization Opportunity",
  "description": "Identifies situations where resource allocation could be optimized",
  "definition": "A scenario where hubutilpct < 30 while simultaneously having distributionpoints > 20, suggesting potential for redistribution of resources to maximize efficiency"
}

{
  "id": 23,
  "knowledge": "Vulnerable Population Hotspot",
  "description": "Identifies areas with highly vulnerable populations requiring priority attention",
  "definition": "Areas where vulnerabilityreview is 'Complete' with distequityidx < 0.3 AND coordeffectlvl is 'Low', indicating populations with high vulnerability and inadequate coordination support"
}

{
  "id": 24,
  "knowledge": "Operational Excellence",
  "description": "Identifies disaster response operations demonstrating superior performance",
  "definition": "Operations with deliverysuccessrate > 90 AND invaccpct > 95 AND OEI > 3, representing highly effective logistics and resource management"
}

{
  "id": 25,
  "knowledge": "Sustainable Response Operation",
  "description": "Identifies disaster responses with strong sustainability practices",
  "definition": "Operations where EIF < 50 AND renewenergypct > 30 AND recyclepct > 60, demonstrating environmental responsibility during emergency response"
}

{
  "id": 26,
  "knowledge": "Public Health Emergency",
  "description": "Identifies situations with severe public health implications",
  "definition": "Conditions where diseaserisk is 'High' AND waterqualityindex < 50 AND PHRS < 40, indicating critical threats to public health requiring immediate intervention"
}

{
  "id": 27,
  "knowledge": "Financial Crisis Risk",
  "description": "Identifies operations at risk of financial collapse",
  "definition": "Operations where fundsutilpct > 80 AND fundingstate is 'Critical' AND FSR < 0.2, indicating severe financial strain that threatens operational continuity"
}

{
  "id": 28,
  "knowledge": "Community Resilience Builder",
  "description": "Identifies operations that strengthen local community capacity",
  "definition": "Operations where localcapacitygrowth is 'Active' AND commengagelvl is 'High' AND BSI > 70, representing efforts that effectively build sustainable community resilience"
}

{
  "id": 29,
  "knowledge": "Logistics Breakdown",
  "description": "Identifies severe disruptions in the supply chain",
  "definition": "Situations where LPM < 30 AND lastmilestatus is 'Suspended' AND vehiclebreakrate > 15, indicating critical failures in the logistics system requiring immediate intervention"
}

{
  "id": 30,
  "knowledge": "Response Time Effectiveness Ratio (RTER)",
  "description": "Measures how quickly and effectively disaster response operations are deployed",
  "definition": "RTER = \\frac{100}{estdurationdays + 1} \\times \\frac{deliverysuccessrate}{100} \\times \\left(\\frac{4 - respphase\\_numeric}{3}\\right), \\text{ where respphase\\_numeric maps Initial=1, Emergency=2, Recovery=3, Reconstruction=4, else=0, representing faster deployment relative to disaster phase}"
}

{
  "id": 31,
  "knowledge": "Resource Distribution Equity (RDE)",
  "description": "Evaluates the fairness of resource distribution across affected areas",
  "definition": "RDE = distequityidx \\times \\left(1 + \\frac{distributionpoints}{20}\\right) \\times \\left(1 - \\frac{100 - deliverysuccessrate}{100}\\right) \\times coordeffect\\_factor, \\text{ where coordeffect\\_factor is 1.2 for High, 1.0 for Medium, 0.8 for Low coordination effectiveness level, and 0 for else}"
}

{
  "id": 32,
  "knowledge": "Communication Resilience Factor (CRF)",
  "description": "Measures the resilience of communication systems during disasters",
  "definition": "CRF = 100 - \\frac{CSR}{2} \\times communication\\_factor, \\text{ where communication\\_factor is 1.0 for Operational, 0.6 for Limited, and 0.3 for Down communication status from impactMetrics.communication}"
}

{
  "id": 33,
  "knowledge": "Supply Chain Sustainability Index (SCSI)",
  "description": "Assesses the environmental sustainability of the disaster supply chain",
  "definition": "SCSI = 100 - EIF \\times \\frac{totaldeliverytons}{1000} \\times \\left(\\frac{fuelefficiencylpk}{20}\\right), \\text{ where EIF measures the environmental impact and higher scores represent more sustainable supply chains}"
}

{
  "id": 34,
  "knowledge": "Staffing to Need Ratio (SNR)",
  "description": "Evaluates whether staffing levels match operational requirements",
  "definition": "SNR = \\frac{staffingprofile->>'personnel'->>'total'}{(impactMetrics->>'population'->>'affected'/10000)} \\times PER \\times ppe\\_factor, \\text{ where ppe\\_factor is 1.2 for Adequate, 0.8 for Limited, 0.5 for Critical PPE status, and 0 for else}"
}

{
  "id": 35,
  "knowledge": "Financial Efficiency Metric (FEM)",
  "description": "Measures the cost-effectiveness of disaster operations",
  "definition": "FEM = \\frac{benefeedbackscore}{costbeneusd} \\times FSR \\times \\left(1 + \\frac{OEI}{10}\\right), \\text{ where higher scores represent more efficient use of financial resources}"
}

{
  "id": 36,
  "knowledge": "Logistics Network Resilience (LNR)",
  "description": "Quantifies the ability of the logistics network to withstand disruption",
  "definition": "LNR = LPM \\times \\frac{vehiclecount}{20} \\times lastmile\\_factor, \\text{ where lastmile\\_factor is 1.0 for On Track, 0.7 for Delayed, 0.4 for Suspended lastmilestatus, 0 for else}"
}

{
  "id": 37,
  "knowledge": "Health System Capacity Index (HSCI)",
  "description": "Measures the disaster area's health system ability to handle medical emergencies",
  "definition": "HSCI = PHRS \\times medcap\\_numeric \\times \\left(1 - \\frac{hazlevel\\_numeric}{6}\\right), \\text{ where medcap\\_numeric maps Adequate=1.0, Limited=0.6, Critical=0.3, else=0 for medical emergency capacity, and hazlevel\\_numeric represents severity level from 1-5}"
}

{
  "id": 38,
  "knowledge": "Community Engagement Effectiveness (CEE)",
  "description": "Evaluates how effectively operations engage with affected communities",
  "definition": "CEE = \\frac{BSI}{100} \\times commengage\\_numeric \\times \\left(\\frac{stakeholdersatisf + 1}{5}\\right), \\text{ where commengage\\_numeric maps Low=1, Medium=2, High=3, else=0 for community engagement level}"
}

{
  "id": 39,
  "knowledge": "Cross-Agency Coordination Index (CACI)",
  "description": "Quantifies how effectively multiple agencies coordinate during disaster response",
  "definition": "CACI = \\frac{partnerorgs}{10} \\times coordeffect\\_numeric \\times \\left(\\frac{infosharing\\_numeric + 1}{3}\\right), \\text{ where coordeffect\\_numeric maps Low=1, Medium=2, High=3, else=0 and infosharing\\_numeric maps Poor=1, Limited=2, Effective=3, else=0}"
}

{
  "id": 40,
  "knowledge": "Critical Resource Prioritization Need",
  "description": "Identifies operations requiring immediate resource redistribution",
  "definition": "Operations experiencing Critical Resource Shortage where PER < 0.5 AND emerglevel is either 'Red' or 'Black', indicating a severe mismatch between available resources and critical operational needs"
}

{
  "id": 41,
  "knowledge": "High-Impact Communication Failure",
  "description": "Identifies disaster areas with severe communication infrastructure breakdown",
  "definition": "Areas where impactMetrics.communication is 'Down' AND CRF < 40 AND coordeffectlvl is 'Low', representing critical communication failures that severely impede response coordination"
}

